import{z as r,x as s,o as n,c as d,q as o,j as i,D as e,d as B,s as l,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"银行债对公开债","description":"","frontmatter":{"title":"银行债对公开债","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bank-vs-public-debt.md","filePath":"econ/bank-vs-public-debt.md","lastUpdated":1791063341000}'),p={name:"econ/bank-vs-public-debt.md"};function D(m,a,u,C,h,b){const t=s("Mermaid");return n(),d("div",null,[a[2]||(a[2]=o('<h1 id="银行债对公开债" tabindex="-1">银行债对公开债 <a class="header-anchor" href="#银行债对公开债" aria-label="Permalink to &quot;银行债对公开债&quot;">​</a></h1><div class="epigraph"><p>银行债集中、可监督、易再谈判；公开债分散、条款标准化、再谈判贵。企业不只选多少债，还选债是向谁借的。</p><footer>—— Diamond, Monitoring and Reputation: The Choice between Bank Loans and Directly Placed Debt, Journal of Political Economy 1991；Rajan, Insiders and Outsiders, Journal of Finance 1992</footer></div><p><a href="/econ/covenants">上一课</a>把条款写成可验证检查。本课缺口是债权人类型：银行为何能执行更紧、更状态依存的监督，公开债市场为何仍被使用。不重写 Smith–Warner 清单，不把<a href="/econ/why-intermediaries">中介为何存在</a>从零讲起——只接到企业负债结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Diamond（1991）：银行作为监督者避免重复监测，声誉好的企业毕业到公开债，节省监督成本；声誉不足的用银行债。Rajan（1992）：银行知情后有套牢（hold-up），知情租金抽取可能扭曲投资，于是企业需要公开债或多元银行来制衡。缺口是：银行债「更好监督」不是免费，信息垄断是代价。资本结构动态因此多一维：私募 vs 公募。</p><p><span class="marginnote">「套牢」的大白话版：你把自家底细告诉了唯一肯放贷的银行，等你急着续借或上项目时，它知道你离了它不行，于是抬价。信息越私密、替代债权人越少，被套牢得越狠——这不是银行「坏」，是知情租金的正常形态。</span></p><p><span class="marginnote">Houston–James 等实证：成长机会多的企业更怕套牢，倾向多元信贷或公开债。有形资产多、监督收益高的用银行。机制课不堆回归，只标这两股力量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较三项：监督强度、再谈判成本、流动性/展期。银行：贷款合同条款紧、豁免常见、展期是关系的一部分。公开债：持有人分散，信托人行动慢，条款松（否则技术性违约无法协调），但定价透明、可交易。混合结构（银行优先、公募在后）把监督放在先偿，公开债搭便车——后课空壳债权人会把搭便车写坏。</p><p>与期限：银行贷款往往短、可催收；公开债更长。上一课的展期风险在银行侧是关系能否续，在公募侧是市场能否发行。</p>',10)),(n(),i(A,null,{default:e(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BANK%5B%22%E9%93%B6%E8%A1%8C%E5%80%BA%22%5D%20--%3E%20MON%5B%22%E9%9B%86%E4%B8%AD%E7%9B%91%E7%9D%A3%22%5D%0A%20%20BANK%20--%3E%20HU%5B%22%E7%9F%A5%E6%83%85%E5%A5%97%E7%89%A2%22%5D%0A%20%20PUB%5B%22%E5%85%AC%E5%BC%80%E5%80%BA%22%5D%20--%3E%20ARM%5B%22%E5%88%86%E6%95%A3%2C%20%E5%86%8D%E8%B0%88%E5%88%A4%E8%B4%B5%22%5D%0A%20%20PUB%20--%3E%20EXIT%5B%22%E6%AF%95%E4%B8%9A%20%2F%20%E4%BB%B7%E6%A0%BC%E9%80%8F%E6%98%8E%22%5D%0A%20%20MIX%5B%22%E6%B7%B7%E5%90%88%22%5D%20--%3E%20FREE%5B%22%E5%85%AC%E5%8B%9F%E6%90%AD%E4%BE%BF%E8%BD%A6%E9%93%B6%E8%A1%8C%E7%9B%91%E7%9D%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"Tirole：最优是状态依存的债权人结构——平时银行监督，危机时需要分散债权人的承诺不豁免（硬预算）。这与 Dewatripont–Maskin 的硬预算约束同方向。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是信息生产与再谈判外部性。银行付监测成本，获得私人信号，再谈判可以避免无效率清算（减轻积压），也可以在好状态下抽取租金（加重套牢）。公开债把信号变成价格，但协调失败使无效率清算更常见。企业事前在「灵活但可能被剥削」与「僵硬但承诺」之间选。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：银行债像请私人医生——了解你的全部病史、随时调整处方，但病历攥在他手里，换医生很难；公开债像挂普通门诊——谁都能接诊、价格透明，但没人真正了解你，出了急症（财务困境）协调一堆科室反而慢。")],-1)),a[7]||(a[7]=E("p",null,"与 Leland：违约边界取决于谁决定是否加速到期。银行更可能重组而不是清算，有效 \\(\\alpha\\) 下降，最优杠杆可以更高——若套牢不抵消。",-1)),(n(),i(A,null,{default:e(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BC%81%E4%B8%9A%E8%A6%81%E5%8F%91%E5%80%BA%EF%BC%9A%E5%90%91%E8%B0%81%E5%80%9F%EF%BC%9F%22%5D%20--%3E%20REPU%5B%22%E5%A3%B0%E8%AA%89%E5%B7%B2%E5%BB%BA%E7%AB%8B%E3%80%81%E4%BF%A1%E6%81%AF%E8%B6%B3%E5%A4%9F%E9%80%8F%E6%98%8E%22%5D%0A%20%20REPU%20--%3E%20PUB%5B%22%E6%AF%95%E4%B8%9A%E5%8E%BB%E5%85%AC%E5%BC%80%E5%80%BA%EF%BC%9A%E7%9C%81%E6%8E%89%E9%87%8D%E5%A4%8D%E7%9B%91%E7%9D%A3%22%5D%0A%20%20Q%20--%3E%20GROW%5B%22%E6%88%90%E9%95%BF%E6%9C%BA%E4%BC%9A%E5%A4%9A%EF%BC%8C%E6%9C%80%E6%80%95%E8%A2%AB%E5%A5%97%E7%89%A2%22%5D%0A%20%20GROW%20--%3E%20MULTI%5B%22%E5%A4%9A%E5%85%83%E9%93%B6%E8%A1%8C%E6%88%96%E5%85%AC%E5%BC%80%E5%80%BA%E5%81%9A%E5%88%B6%E8%A1%A1%22%5D%0A%20%20Q%20--%3E%20NEED%5B%22%E9%9C%80%E8%A6%81%E7%B4%A7%E7%9B%91%E7%9D%A3%E4%B8%8E%E7%81%B5%E6%B4%BB%E5%B1%95%E6%9C%9F%22%5D%0A%20%20NEED%20--%3E%20BANK%5B%22%E9%93%B6%E8%A1%8C%E5%80%BA%EF%BC%9A%E8%B1%81%E5%85%8D%E4%B8%8E%E5%86%8D%E8%B0%88%E5%88%A4%E5%9C%A8%E6%89%8B%22%5D%0A%20%20BANK%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E7%9F%A5%E6%83%85%E7%A7%9F%E9%87%91%E4%B8%8E%E5%9E%84%E6%96%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<h3 id="不是「银行债总是关系、公募总是距离」" tabindex="-1">不是「银行债总是关系、公募总是距离」 <a class="header-anchor" href="#不是「银行债总是关系、公募总是距离」" aria-label="Permalink to &quot;不是「银行债总是关系、公募总是距离」&quot;">​</a></h3><p>交易型银行贷款（辛迪加、可转让）把银行债做成准公开。公开债的集中持有（保险公司、贷款基金）可以把公募做成准银行。本课用监督与再谈判成本分类，不用户口分类。</p><p><span class="marginnote">主干里信贷配给、Diamond–Dybvig 已解释银行为何存在。本课站在企业：给定银行存在，负债菜单如何切。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成贷款合同模板。下一课关系借贷把套牢与信息的跨期保险展开。证券化会把银行债再变成可交易，改变监督激励。</p><p>后课默认：银行 vs 公开是监督与套牢、再谈判与承诺的权衡。混合结构有搭便车。条款的硬度取决于债权人类型。</p><p>不要进入限价簿上的公司债做市价差；那是交易协议。</p><p><span class="marginnote">常见误区：「公开债利率低，所以比银行债划算。」利率差买的是监督与再谈判服务；对信息不透明的企业，公开债的低息往往伴随更松的条款协调与更贵的违约处理。比价格，更要比条款的硬度和出了事谁有权说不。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>银行：监督与再谈判强，知情套牢是代价；公开债相反。</li><li>声誉毕业、成长企业防套牢，决定菜单，而不只是杠杆率。</li><li>谁持有债，改变有效破产成本与违约边界。</li><li>出处：Diamond, <em>JPE</em> 1991；Rajan, <em>JF</em> 1992。</li></ul>',10))])}const F=r(p,[["render",D]]);export{f as __pageData,F as default};
